/* domain/order.h - storage-free */
typedef struct { order_id id; int qty; money_t total; } order_t;
bool order_confirm(order_t *o, error_t **err);   /* invariants here */

/* infra/order_repo.c - row shape + mapping live here */
typedef struct { long long id; int qty; long long total_cents; } order_row_t;
static void order_from_row(const order_row_t *r, order_t *out) {
    out->id = (order_id)r->id;
    out->qty = r->qty;
    out->total = money_from_cents(r->total_cents);   /* validates */
}
